{E : Type*} [NormedAddCommGroup E] [InnerProductSpace ℝ E] [FiniteDimensional ℝ E] [MeasurableSpace E] [BorelSpace E]
  (L : Submodule ℤ E) [DiscreteTopology L] [IsZLattice ℝ L] {ι : Type*} [Fintype ι] (b : Basis ι ℤ L) {s : Set E}
  (hs : NullMeasurableSet s) : volume ((b.ofZLatticeBasis ℝ).equivFun '' s) = volume s / ENNReal.ofReal (covolume L)

∀ {C : Type u} {inst : CategoryTheory.Category.{v, u} C} {P : CategoryTheory.MorphismProperty C} {X Y : C} {f : X ⟶ Y}
  [self : P.IsStableUnderBaseChangeAlong f] {Z W : C} {f' : W ⟶ Z} {g' : W ⟶ X} {g : Z ⟶ Y},
  CategoryTheory.IsPullback f' g' g f → P g → P g'

∀ {C : Type u₁} {D : Type u₂} {inst : CategoryTheory.Category.{v₁, u₁} C} {inst_1 : CategoryTheory.Category.{v₂, u₂} D}
  {x y : C ≌ D},
  x = y ↔ x.functor = y.functor ∧ x.inverse = y.inverse ∧ x.unitIso ≍ y.unitIso ∧ x.counitIso ≍ y.counitIso

∀ {C : Type u} {inst : CategoryTheory.Category.{v, u} C} {P : CategoryTheory.MorphismProperty C}
  [self : P.IsStableUnderBaseChange] {X Y Y' S : C} {f : X ⟶ S} {g : Y ⟶ S} {f' : Y' ⟶ Y} {g' : Y' ⟶ X},
  CategoryTheory.IsPullback f' g' g f → P g → P g'

∀ {C : Type u₁} [inst : CategoryTheory.Category.{v₁, u₁} C] {P : C} (X Y : C) {Z : C} {fst fst_1 : P ⟶ X}
  (e_fst : fst = fst_1) {snd snd_1 : P ⟶ Y} (e_snd : snd = snd_1) {f f_1 : X ⟶ Z} (e_f : f = f_1) {g g_1 : Y ⟶ Z}
  (e_g : g = g_1) {P' : C} {fst' fst'_1 : P' ⟶ X} (e_fst' : fst' = fst'_1) {snd' snd'_1 : P' ⟶ Y}
  (e_snd' : snd' = snd'_1) (h : CategoryTheory.IsPullback fst snd f g) (h' : CategoryTheory.IsPullback fst' snd' f g),
  CategoryTheory.IsPullback.isoIsPullback X Y h h' = Categor...

